// A function returning a temporary vector of bools
std::vector<bool> makeVector() {
    return {false, true, false, true, true};
}

// auto deduces the proxy type, std::vector<bool>::reference
auto problematic_val = makeVector()[0]; 

// At this point, the temporary vector from makeVector() is destroyed.
// `problematic_val` now holds a proxy object with a dangling pointer
// to the temporary's internal storage.
// Using `problematic_val` results in undefined behavior.

// The fix: Use an explicit cast to force the proxy's conversion
auto correct_val = static_cast<bool>(makeVector()[0]);
// `correct_val` is now a safe, independent bool.
